import { describe, expect, it } from 'vitest'
import { hasPrivateLink, scrub } from './scrub-links.mjs'

const session = 'https://claude.ai/code/session_01XAhviBkntcU8LhR53kB6c9'
const thread = 'https://claude.ai/code/project/chan_01ABC?thread=cmsg_01DEF'

describe('scrub', () => {
  it('points a footer link at the product page', () => {
    expect(scrub(`---\n_Generated by [Claude Code](${session})_`)).toBe(
      '---\n_Generated by [Claude Code](https://claude.ai/code)_',
    )
  })
  it('drops a project thread link and its separator', () => {
    expect(scrub(`_Requested by **Chris** · [project thread](${thread})_\n\nBody`)).toBe(
      '_Requested by **Chris**_\n\nBody',
    )
  })
  it('removes bare link lines and session trailers', () => {
    expect(scrub(`🤖 Generated with Claude Code\n\n${session}\n`)).toBe('🤖 Generated with Claude Code\n\n')
    expect(scrub(`Fix it\n\nClaude-Session: ${session}\nCo-Authored-By: X`)).toBe('Fix it\n\nCo-Authored-By: X')
  })
  it('covers chat and share links', () => {
    expect(hasPrivateLink('see https://claude.ai/chat/1234-abcd')).toBe(true)
    expect(scrub('see https://claude.ai/share/1234-abcd for details')).toBe('see https://claude.ai/code for details')
  })
  it('leaves the product page and other text alone', () => {
    const text = 'Built with [Claude Code](https://claude.ai/code) and https://claude.com/claude-code'
    expect(hasPrivateLink(text)).toBe(false)
    expect(scrub(text)).toBe(text)
  })
  it('handles empty bodies', () => {
    expect(scrub(null)).toBe(null)
    expect(scrub('')).toBe('')
  })
})
